import Link from "next/link";
import { PrismaClient } from "@prisma/client";

export const instant = false;
const prisma = new PrismaClient();

// قائمة الأقسام (مؤقتة للديكور، بعدين فيك تربطها بالداتابيز)
const categories = [
  "أجهزة الكترونية", "موضة نسائية", "موضة رجالية", 
    "هواتف وإكسسوارات", "أدوات منزلية", "عطور", 
      "ساعات", "رياضة", "ألعاب"
      ];

      async function ProductList() {
        const products = await prisma.product.findMany({
            orderBy: { createdAt: "desc" },
              });

                if (products.length === 0) {
                    return <p className="text-center text-gray-500 py-10 w-full">ما في منتجات حالياً.</p>;
                      }

                        return (
                            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3 md:gap-4">
                                  {products.map((product) => (
                                          <Link key={product.id} href={`/product?slug=${product.slug}`} className="group block bg-white rounded-lg overflow-hidden hover:shadow-xl transition-all duration-300 border border-gray-100 relative">
                                                    
                                                              {/* صورة المنتج */}
                                                                        <div className="relative w-full h-40 sm:h-48 bg-gray-50 overflow-hidden">
                                                                                    {product.imageUrl ? (
                                                                                                  <img 
                                                                                                                  src={product.imageUrl} 
                                                                                                                                  alt={product.name} 
                                                                                                                                                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" 
                                                                                                                                                                />
                                                                                                                                                                            ) : (
                                                                                                                                                                                          <div className="w-full h-full flex items-center justify-center text-gray-400 text-sm">لا صورة</div>
                                                                                                                                                                                                      )}
                                                                                                                                                                                                                  <div className="absolute top-0 left-0 bg-red-500 text-white text-[10px] font-bold px-2 py-0.5 rounded-br-lg z-10 shadow-sm">
                                                                                                                                                                                                                                خصم 15%
                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                {/* تفاصيل المنتج */}
                                                                                                                                                                                                                                                                          <div className="p-2 sm:p-3">
                                                                                                                                                                                                                                                                                      <h2 className="text-xs sm:text-sm font-medium text-gray-800 line-clamp-2 leading-tight h-9">
                                                                                                                                                                                                                                                                                                    {product.name}
                                                                                                                                                                                                                                                                                                                </h2>
                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                        <div className="mt-1 flex items-center gap-1">
                                                                                                                                                                                                                                                                                                                                                      <span className="text-orange-400 text-[10px] sm:text-xs">★★★★★</span>
                                                                                                                                                                                                                                                                                                                                                                    <span className="text-gray-400 text-[10px]">(2.5k)</span>
                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                            
                                                                                                                                                                                                                                                                                                                                                                                                        <div className="mt-1 flex items-baseline gap-1 flex-wrap">
                                                                                                                                                                                                                                                                                                                                                                                                                      <p className="text-base sm:text-lg font-black text-red-600">
                                                                                                                                                                                                                                                                                                                                                                                                                                      ${(product.price / 100).toFixed(2)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                    </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-[10px] text-gray-400 line-through">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ${((product.price * 1.15) / 100).toFixed(2)}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div className="mt-1 flex items-center justify-between">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <p className="text-[10px] text-green-600 font-bold bg-green-50 px-1 rounded">شحن مجاني</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <p className="text-[10px] text-gray-400">تم البيع 100+</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          export default async function Home() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <main className="max-w-7xl mx-auto p-2 sm:p-4 bg-gray-50 min-h-screen" dir="rtl">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {/* الهيكل الرئيسي: قائمة أقسام + بانر ومنتجات */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <div className="flex gap-4">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  {/* القائمة الجانبية (Sidebar) */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <aside className="hidden md:block w-56 shrink-0 bg-white rounded-xl shadow-sm border border-gray-100 p-3 h-fit sticky top-20">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <h3 className="font-bold text-gray-800 mb-3 border-b pb-2 flex items-center gap-2">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span>☰</span> كل الأقسام
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </h3>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <ul className="space-y-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {categories.map((cat, i) => (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <li key={i}>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <Link href="#" className="block px-3 py-2 text-sm text-gray-600 rounded-lg hover:bg-red-50 hover:text-red-600 transition-colors">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {cat}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </li>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ))}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </ul>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </aside>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {/* المحتوى الرئيسي */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="flex-1">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* البانر الإعلاني */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <div className="w-full bg-gradient-to-l from-red-600 via-orange-500 to-yellow-400 rounded-xl mb-6 p-6 sm:p-10 flex items-center justify-between text-white shadow-md relative overflow-hidden">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <div className="relative z-10">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <h1 className="text-3xl sm:text-5xl font-black mb-2">تخفيضات الميجا سيل!</h1>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        <p className="text-sm sm:text-lg opacity-95 font-medium">خصومات تصل لـ 70% | توصيل سريع لكل لبنان</p>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <button className="mt-4 bg-white text-red-600 font-bold px-6 py-2 rounded-full hover:bg-gray-100 transition-colors shadow-lg">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      تسوق الآن
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    </button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <span className="text-7xl sm:text-9xl opacity-30 absolute -left-4 -bottom-4">🛍️</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {/* عنوان المنتجات */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div className="flex items-center justify-between mb-4 bg-white p-3 rounded-lg shadow-sm border border-gray-100">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <h2 className="text-lg font-bold text-gray-800 border-r-4 border-red-500 pr-2">توصيات لك</h2>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  <Link href="#" className="text-sm text-gray-500 hover:text-red-500">مشاهدة الكل</Link>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {/* شبكة المنتجات */}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <ProductList />
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </main>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }